-- ----------------------------------------------------------------------------
-- 3. Las zonas de ejemplo de cada CRM pasan a ser su zona oficial (mismo id: sus leads no cambian)
-- ----------------------------------------------------------------------------
-- La validación de país habilitado se suspende solo aquí: una zona de un país que un CRM ya no
-- tiene habilitado también debe quedar con su código oficial, para no duplicarse si lo reactiva.
ALTER TABLE public.territories DISABLE TRIGGER trg_territories_country_enabled;

WITH mapa(viejo, nuevo) AS (
    VALUES ('PROV-01', 'CL-13123'), ('LC-02', 'CL-13114'), ('STGO-03', 'CL-13101'), ('VIT-04', 'CL-13132'),
           ('NUN-05', 'CL-13120'), ('LIM-SI', 'PE-150131'), ('LIM-MF', 'PE-150122'), ('LIM-SU', 'PE-150140'),
           ('LIM-SB', 'PE-150130'), ('LIM-LM', 'PE-150114')
)
UPDATE public.territories t
SET code = z.code,
    name = z.name,
    category = z.category,
    polygon = z.polygon,
    region_code = z.region_code,
    region_name = z.region_name,
    province_name = z.province_name,
    region_order = z.region_order
FROM mapa m
JOIN public.zone_catalog z ON z.code = m.nuevo
WHERE t.code = m.viejo AND t.country_code = z.country_code;

ALTER TABLE public.territories ENABLE TRIGGER trg_territories_country_enabled;

DELETE FROM public.zone_catalog
WHERE code IN ('PROV-01', 'LC-02', 'STGO-03', 'VIT-04', 'NUN-05', 'LIM-SI', 'LIM-MF', 'LIM-SU', 'LIM-SB', 'LIM-LM');

-- ----------------------------------------------------------------------------
-- 4. La copia al CRM lleva también región y provincia
-- ----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.seed_company_territories(p_company_id UUID)
RETURNS INTEGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_total INTEGER;
BEGIN
    INSERT INTO public.territories
        (company_id, country_code, name, code, category, color_hex, polygon, region_code, region_name, province_name, region_order)
    SELECT p_company_id, z.country_code, z.name, z.code, z.category, z.color_hex, z.polygon,
           z.region_code, z.region_name, z.province_name, z.region_order
    FROM public.zone_catalog z
    WHERE public.is_country_enabled(p_company_id, z.country_code)
      AND NOT EXISTS (
          SELECT 1 FROM public.territories t WHERE t.company_id = p_company_id AND t.code = z.code
      )
    ON CONFLICT DO NOTHING;
    GET DIAGNOSTICS v_total = ROW_COUNT;
    RETURN v_total;
END;
$$;

REVOKE EXECUTE ON FUNCTION public.seed_company_territories(UUID) FROM PUBLIC, anon, authenticated;

-- Los CRMs que ya existen reciben ahora el resto de sus zonas oficiales
SELECT public.seed_company_territories(c.id) FROM public.companies c;

-- ----------------------------------------------------------------------------
-- 5. El mapa recibe también región y provincia
-- ----------------------------------------------------------------------------
CREATE OR REPLACE VIEW public.territories_geojson
WITH (security_invoker = true) AS
SELECT
    t.id,
    t.company_id,
    t.country_code,
    t.name,
    t.code,
    t.color_hex,
    extensions.ST_AsGeoJSON(t.polygon)::jsonb AS polygon,
    t.region_code,
    t.region_name,
    t.province_name,
    t.region_order
FROM public.territories t;

COMMENT ON VIEW public.territories_geojson IS
    'Zonas del CRM con el polígono en GeoJSON, su región y provincia, para el mapa y los selectores. security_invoker: aplica el RLS de territories.';
